142	    async fn refresh(&mut self, url: &Url) -> eyre::Result<bool> {
143	        if let LoginInfo::OAuth {
144	            token,
145	            refresh_token,
146	            expires_at,
147	            ..
148	        } = self
149	        {
150	            if time::OffsetDateTime::now_utc() >= *expires_at {
151	                let api = Forgejo::with_user_agent(Auth::None, url.clone(), crate::USER_AGENT)?;
152	                let client_id = crate::auth::get_client_info_for(url)
153	                    .await?
154	                    .ok_or_else(|| eyre::eyre!("Can't refresh token: no client info for {url}."))?;
155	                let response = api
156	                    .oauth_get_access_token(forgejo_api::structs::OAuthTokenRequest::Refresh {
157	                        refresh_token,
158	                        client_id: &client_id,
159	                        client_secret: "",
160	                    })
161	                    .await?;
162	                *token = response.access_token;
163	                *refresh_token = response.refresh_token;
164	                // A minute less, in case any weirdness happens at the exact moment it
165	                // expires. Better to refresh slightly too soon than slightly too late.
166	                let expires_in =
167	                    std::time::Duration::from_secs(response.expires_in.saturating_sub(60) as u64);
168	                *expires_at = time::OffsetDateTime::now_utc() + expires_in;
169	                return Ok(true);
170	            }
171	        }
172	        Ok(false)
173	    }
